#!/usr/bin/env node
/**
 * Runs the JS-side scenarios for every implementation, once per round.
 *
 * - Each implementation runs in its own Jest process, so global state (Tamagui config,
 *   NativeWind's registered CSS) cannot leak into another library's measurements.
 * - Each round uses a different order, generated by a seeded shuffle. This reduces
 *   ordering and thermal bias. The seed is recorded, so the order can be reproduced.
 * - Raw samples go to results/raw/round-<r>-<impl>.json. Environment details go to
 *   results/meta.json.
 *
 * Usage: node scripts/run-benchmark.js [--rounds 3] [--trials 30] [--warmup 5] [--steps 12]
 *                                      [--impls stylesheet,vajra,...]
 *        node scripts/run-benchmark.js --smoke [--impls ...]
 *          Smoke: 100 cards, 1 round, 3 trials, 1 warm-up. Output goes to results/smoke/.
 *
 * For the same scenarios inside the iOS simulator or Android emulator, see
 * run-device-benchmark.js.
 */
const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const { ROOT, RESULTS, parseArgs, orderPlan, clearRaw, collectMeta } = require('./bench-common');

const SMOKE = process.argv.includes('--smoke');
// Smoke runs write to their own folder so they never replace the real results.
const RAW = path.join(RESULTS, SMOKE ? 'smoke' : 'raw');
const JEST_BIN = path.join(ROOT, 'node_modules', 'jest', 'bin', 'jest.js');

// Unistyles is excluded: it needs its native runtime and is measured on a simulator or device.

const runOne = (impl, round, opts) => {
  const out = path.join(RAW, `round-${round}-${impl}.json`);
  const env = {
    ...process.env,
    BENCH_IMPL: impl,
    BENCH_OUT: out,
    BENCH_ROUND: String(round),
    BENCH_TRIALS: String(opts.trials),
    BENCH_WARMUP: String(opts.warmup),
    BENCH_STEPS: String(opts.steps),
    BENCH_SMOKE: SMOKE ? '1' : '',
  };
  const result = spawnSync(
    process.execPath,
    [
      '--expose-gc',
      JEST_BIN,
      '--config',
      'jest.config.js',
      '--testMatch',
      '<rootDir>/scenarios/*.scenario.tsx',
      '--runInBand',
    ],
    { cwd: ROOT, env, stdio: 'inherit' },
  );
  if (result.status !== 0) {
    throw new Error(`Round ${round}, ${impl} failed with exit code ${result.status}`);
  }
};

const main = () => {
  const opts = parseArgs(process.argv.slice(2));
  clearRaw(RAW, opts.impls);

  const plan = orderPlan(opts);
  for (const { round, order } of plan) {
    console.log(`\n=== Round ${round}/${opts.rounds}: order ${order.join(' → ')}`);
    for (const impl of order) runOne(impl, round, opts);
  }

  fs.writeFileSync(
    path.join(SMOKE ? RAW : RESULTS, 'meta.json'),
    JSON.stringify({ ...collectMeta(opts), runtime: 'jest', orderPlan: plan }, null, 2),
  );
  console.log(`\nWrote ${opts.rounds * opts.impls.length} raw files to ${RAW}`);
};

main();
